using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Mvc;using TransPort.Api.Controllers;using TransPort.Api.Modules.Produccion.DTOs;using TransPort.Api.Modules.Produccion.Repositories;
namespace TransPort.Api.Tests;
public sealed class ProduccionesControllerTests
{
 [Fact]public async Task Listar_PropagaAlcance(){var r=new Fake();await C(r,9,"Empleado").Listar(null,null,null,null,default);Assert.Equal(new AlcanceProduccion(9,false),r.Alcance);}
 [Fact]public async Task Crear_DevuelveId(){var r=new Fake{Id=73};var x=Assert.IsType<OkObjectResult>(await C(r,1,"AdministradorGeneral").Crear(new(){SedeId=1,ArticuloEntradaId=2,ArticuloSalidaId=3,FechaPlanificada=DateTime.Today,CantidadEntrada=10,CantidadSalidaPlanificada=8},default));Assert.Equal(73,Assert.IsType<ResultadoProduccionDto>(x.Value).Id);}
 [Fact]public async Task Obtener_Inexistente_NotFound()=>Assert.IsType<NotFoundResult>(await C(new Fake(),1,"AdministradorGeneral").Obtener(99,default));
 [Fact]public async Task CompletarEtapa_PropagaAlcance(){var r=new Fake();Assert.IsType<NoContentResult>(await C(r,4,"Operativo").CompletarEtapa(1,2,new(),default));Assert.Equal(new AlcanceProduccion(4,false),r.Alcance);}
 [Fact]public void Controlador_ExcluyeCliente(){var a=typeof(ProduccionesController).GetCustomAttributes(typeof(AuthorizeAttribute),true).Cast<AuthorizeAttribute>().Single();Assert.DoesNotContain("Cliente",a.Roles??"");}
 private static ProduccionesController C(IProduccionRepository r,int id,params string[]roles){var cs=new List<Claim>{new(ClaimTypes.NameIdentifier,id.ToString())};cs.AddRange(roles.Select(x=>new Claim(ClaimTypes.Role,x)));return new(r){ControllerContext=new(){HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(cs,"T"))}}};}
 private sealed class Fake:IProduccionRepository{public long Id{get;init;}public AlcanceProduccion?Alcance{get;private set;}public Task<IReadOnlyList<ProduccionListadoDto>>ListarAsync(string?e,int?s,DateTime?d,DateTime?h,AlcanceProduccion a,CancellationToken ct){Alcance=a;return Task.FromResult<IReadOnlyList<ProduccionListadoDto>>([]);}public Task<ProduccionDetalleDto?>ObtenerAsync(long id,AlcanceProduccion a,CancellationToken ct){Alcance=a;return Task.FromResult<ProduccionDetalleDto?>(null);}public Task<ProduccionOpcionesDto>OpcionesAsync(AlcanceProduccion a,CancellationToken ct)=>Task.FromResult(new ProduccionOpcionesDto([],[]));public Task<long>CrearAsync(CrearProduccionRequest x,AlcanceProduccion a,CancellationToken ct){Alcance=a;return Task.FromResult(Id);}public Task<bool>CambiarEstadoAsync(long id,CambiarEstadoProduccionRequest x,AlcanceProduccion a,CancellationToken ct){Alcance=a;return Task.FromResult(true);}public Task<bool>CompletarEtapaAsync(long id,long etapaId,string?o,AlcanceProduccion a,CancellationToken ct){Alcance=a;return Task.FromResult(true);}public Task<bool>EliminarAsync(long id,int u,CancellationToken ct)=>Task.FromResult(true);}
}
